## 💻 Sample Producer Client Implementation (Java 25)

```java
package org.opencrawling.example;

import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import io.grpc.Metadata;
import io.grpc.stub.MetadataUtils;
import org.opencrawling.push.v1.*;

import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.Map;

public class PushConnectorExample {

    public static void main(String[] args) {
        ManagedChannel channel = ManagedChannelBuilder.forAddress("localhost", 9096)
                .usePlaintext()
                .build();

        // Attach Bearer token metadata
        Metadata headers = new Metadata();
        Metadata.Key<String> authKey = Metadata.Key.of("authorization", Metadata.ASCII_STRING_MARSHALLER);
        headers.put(authKey, "Bearer my-secure-ingest-token");

        OisPushServiceGrpc.OisPushServiceBlockingStub client = 
                MetadataUtils.attachHeaders(OisPushServiceGrpc.newBlockingStub(channel), headers);

        // Build OIS Document Payload with Zero-Trust ACLs
        OisDocumentPayload doc = OisDocumentPayload.newBuilder()
                .setId("contract://legal/2026/NDA-8492.pdf")
                .setAction(DocumentAction.UPSERT)
                .setMimeType("application/pdf")
                .setTimestamp(Instant.now().toEpochMilli())
                .setTextContent("Confidential Mutual Non-Disclosure Agreement between Corp A and Corp B...")
                .putAllMetadata(Map.of(
                        "department", "Legal",
                        "confidentiality", "Strict",
                        "author", "alice@corp.com"
                ))
                .setSecurity(SecurityConfig.newBuilder()
                        .addAllowSids("ROLE_LEGAL")
                        .addAllowSids("alice@corp.com")
                        .addDenySids("ROLE_CONTRACTORS")
                        .setTenantId("ACME_CORP")
                        .build())
                .build();

        // Execute Unary Push
        PushDocumentResponse response = client.pushDocument(PushDocumentRequest.newBuilder()
                .setJobId("legal-documents-rag-pipeline")
                .setDocument(doc)
                .build());

        System.out.printf("Ingestion Response: %s - %s (Processed at: %d)%n",
                response.getStatus(), response.getMessage(), response.getProcessedAt());

        channel.shutdown();
    }
}
```

