## Step 4 — `app/actions/portal.ts` (new file)

```ts
"use server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";

export async function inviteClientToPortalAction(
  clientId: string,
  _prev: { error?: string; success?: boolean } | null,
  formData: FormData
): Promise<{ error?: string; success?: boolean }> {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return { error: "Unauthorized." };

  const email = (formData.get("email") as string)?.trim();
  if (!email) return { error: "Email is required." };

  const { data: profile } = await supabase
    .from("profiles").select("tenant_id, role").eq("id", user.id).single();
  if (!profile || profile.role !== "admin") return { error: "Unauthorized." };

  const { data: client } = await supabase
    .from("clients").select("id").eq("id", clientId).single();
  if (!client) return { error: "Client not found." };

  const admin = createAdminClient();
  const { error } = await admin.auth.admin.inviteUserByEmail(email, {
    data: { role: "client", tenant_id: profile.tenant_id, client_id: clientId },
    redirectTo: `${process.env.NEXT_PUBLIC_APP_URL}/auth/callback`,
  });

  if (error) return { error: error.message };
  return { success: true };
}
```

